CREATE TABLE `User` (`id` CHAR(36) NOT NULL, `email` VARCHAR(320) NULL, `passwordHash` VARCHAR(255) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `User_email_key` (`email`));
CREATE TABLE `Identity` (`id` CHAR(36) NOT NULL, `userId` CHAR(36) NOT NULL, `provider` VARCHAR(40) NOT NULL, `subject` VARCHAR(255) NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE INDEX `Identity_provider_subject_key` (`provider`,`subject`), INDEX `Identity_userId_idx` (`userId`), CONSTRAINT `Identity_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE);
CREATE TABLE `Session` (`id` CHAR(36) NOT NULL, `tokenHash` CHAR(64) NOT NULL, `userId` CHAR(36) NOT NULL, `expiresAt` DATETIME(3) NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE INDEX `Session_tokenHash_key` (`tokenHash`), INDEX `Session_userId_expiresAt_idx` (`userId`,`expiresAt`), CONSTRAINT `Session_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE);
CREATE TABLE `PlayerSave` (`userId` CHAR(36) NOT NULL, `version` INTEGER NOT NULL DEFAULT 1, `state` JSON NOT NULL, `revision` INTEGER NOT NULL DEFAULT 0, `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`userId`), CONSTRAINT `PlayerSave_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE);
CREATE TABLE `IdempotencyRecord` (`id` CHAR(36) NOT NULL, `userId` CHAR(36) NOT NULL, `key` VARCHAR(128) NOT NULL, `response` JSON NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE INDEX `IdempotencyRecord_userId_key_key` (`userId`,`key`), CONSTRAINT `IdempotencyRecord_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE);
CREATE TABLE `EconomyLedger` (`id` CHAR(36) NOT NULL, `userId` CHAR(36) NOT NULL, `eventKey` VARCHAR(180) NOT NULL, `amount` INTEGER NOT NULL, `balanceAfter` INTEGER NOT NULL, `reason` VARCHAR(80) NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE INDEX `EconomyLedger_eventKey_key` (`eventKey`), INDEX `EconomyLedger_userId_createdAt_idx` (`userId`,`createdAt`), CONSTRAINT `EconomyLedger_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE);
CREATE TABLE `Expedition` (`id` CHAR(36) NOT NULL, `userId` CHAR(36) NOT NULL, `queueId` VARCHAR(120) NOT NULL, `planId` VARCHAR(80) NOT NULL, `startedAt` DATETIME(3) NOT NULL, `endsAt` DATETIME(3) NOT NULL, `settledAt` DATETIME(3) NULL, `rewardGold` INTEGER NOT NULL, `rewardXP` INTEGER NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `Expedition_queueId_key` (`queueId`), INDEX `Expedition_settledAt_endsAt_idx` (`settledAt`,`endsAt`), CONSTRAINT `Expedition_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE);
